from hypothesis import strategies as st

@st.composite
def gen(draw):
    n = draw(st.integers(2, 7))
    # Edge cases: minimum M, maximum M, and the middle range.
    m = draw(st.one_of(
        st.just(10 * n - 9),
        st.just(10 * n),
        st.integers(10 * n - 9, 10 * n),
    ))
    return f"{n} {m}\n"

def validate(inp):
    lines = inp.split("\n")
    if len(lines) < 1:
        return False
    parts = lines[0].split()
    if len(parts) != 2:
        return False
    try:
        n, m = int(parts[0]), int(parts[1])
    except ValueError:
        return False
    return 2 <= n <= 12 and 10 * n - 9 <= m <= 10 * n

