    n, m = int(t[0]), int(t[1])
    results = []
    seq = []

    def dfs(i):
        # i = index of the element about to be chosen (0-based)
        if i == n:
            if seq[-1] <= m:
                results.append(list(seq))
            return
        if i == 0:
            lo = 1
        else:
            lo = seq[-1] + 10
        for v in range(lo, m + 1):
            # Remaining elements after v must each be at least 10 more; prune only
            # when it is impossible to still end at or below m.
            if v + 10 * (n - i - 1) > m:
                break
            seq.append(v)
            dfs(i + 1)
            seq.pop()

